// the idea is taken from Danguafer
// https://www.shadertoy.com/view/XsXXDn

#define t iTime
#define r iResolution.xy

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
	vec3 c;
	float l,z=t;
	for(int i=0;i<100;i++) {
		vec2 uv,p=fragCoord.xy/r;
		uv=p;
		p-=.5;
		p.x*=r.x/r.y;
		z+=.800;
		l=length(p);
		uv+=p/l*(sin(z)+02.)*abs(sin(l*4.-z-z));
		c[i]=.035/length(mod(uv,1.)-.5);
	}
	fragColor=vec4(c/l,t);
}
